<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {damageCalculation,weaponMechanics} from '../../../api/src/rules/combat-damage';
import {api,ApiError} from '../lib/api';
const props=defineProps<{campaignId:string;room:any}>(),emit=defineEmits<{changed:[]}>();
const endpoint=`/api/campaigns/${props.campaignId}/combat`,pending=ref<any[]>([]),error=ref(''),busy=ref(false),request=ref<any>(null);
const reactable=ref<any[]>([]),counterAttacks=ref<any[]>([]),reactionDrafts=ref<Record<string,any>>({}),counterDrafts=ref<Record<string,any>>({}),reactionNotice=ref('');
const attackEdge=ref(false),attackPowerId=ref(''),attackContextConfirmed=ref(false),attackDamageVector=ref('');
const attackDistance=ref<number|null>(null),areaDistance=ref<number|null>(null),additionalTargets=ref<string[]>([]),targetDistances=ref<Record<string,number>>({}),intensiveUse=ref(false),matterSpent=ref(2),pursuesImpulse=ref(false);
const obstacleId=ref(''),obstacleKnown=ref(false),obstacleBlocks=ref(false),obstacleError=ref('');
async function testObstacle(){if(busy.value||!props.room.canManage||!attacker.value?.frenzy?.active||!obstacleId.value||!obstacleKnown.value||!obstacleBlocks.value)return;busy.value=true;obstacleError.value='';try{await api(`/api/characters/${attackerId.value}/play`,{method:'POST',body:JSON.stringify({requestId:crypto.randomUUID(),version:attacker.value.version,action:'frenzy-obstacle',obstacleId:obstacleId.value,recognizedCloseConfirmed:true,impulseBlockedConfirmed:true})});await load();emit('changed');}catch(e){obstacleError.value=e instanceof ApiError&&e.status===409?'Le personnage a changé. Actualise et recommence.':'Ce test demande une Frénésie active et un proche qui fait réellement obstacle.';}finally{busy.value=false;}}
watch(obstacleId,()=>{obstacleKnown.value=false;obstacleBlocks.value=false;});
const arcOffers=ref<any[]>([]),arcDrafts=ref<Record<string,any>>({});
const lightningReactions=ref<any[]>([]),allyLightningDrafts=ref<Record<string,any>>({});
const lightningErrors:Record<string,string>={frenzy_impulse_pa_required:'Garde 1 PA pour poursuivre l’impulsion de Frénésie, ou confirme que cette action la poursuit.',foudre_fin_ruling_required:'Le MJ doit confirmer un fléau, les conditions de destruction et un impact réellement mortel.',physical_pa_reserved:'Ce dernier PA est réservé à une action physique par la Crête.',between_states_action_forbidden:'Entre deux états interdit cette attaque physique.',foudre_range_required:'Confirme une cible réellement à 20 m maximum.',foudre_defense_required:'Choisis et confirme la défense pertinente avec le MJ.',paratonnerre_unavailable:'Paratonnerre indisponible : vérifie la Révélation, les PA, le quota et la fenêtre de réaction.',paratonnerre_destination_required:'Indique et confirme un conducteur ou une zone valide proche.',electric_protection_ruling_required:'Le MJ doit confirmer la source et la valeur de cette protection électrique.',invalid_foudre_vector:'La Foudre utilise le vecteur Électricité.',edge_roll_resolved:'Ce résultat est déjà engagé ou résolu et ne peut plus être forcé.'};
const attackPower=computed(()=>attacker.value?.powers?.find((p:any)=>p.id===attackPowerId.value));
const damageVectors=[{id:'melee',label:'Mêlée'},{id:'balistique',label:'Balistique'},{id:'antichoc',label:'Antichoc'},{id:'feu',label:'Feu'},{id:'froid',label:'Froid'},{id:'electricite',label:'Électricité'},{id:'chimique',label:'Chimique'},{id:'occulte',label:'Occulte'},{id:'neuro',label:'Neuro'}];
const attackRulingRequired=computed(()=>!!option.value?.requiresAdjudication);
const attackConditions=computed(()=>[option.value?.condition,attackPower.value?.context,option.value?.requiresAdjudication?'Le MJ a arbitré le type de dégâts de cette arme.':null,option.value?.modeChangeCost?`Le régime ${option.value.mode} est autorisé pour cette arme ; son changement sera payé automatiquement.`:null].filter(Boolean));
const frequency=(limit:string|null)=>limit?({round:'1/round',scene:'1/scène',day:'1/jour',scenario:'1/scénario'} as Record<string,string>)[limit]??limit:'';
const effectText=(effect:any)=>`${effect.amount>=0?'+':''}${effect.amount} ${({damage:'DGT',piercing:'Perforant',skill:'au jet',reduction:'Réduction'} as Record<string,string>)[effect.kind]??effect.kind}`;
const weapons=ref<any[]>([]),weaponId=ref('');
const attackers=ref<any[]>([]),attackerId=ref(''),optionId=ref(''),attackTarget=ref(''),attackBonus=ref(0),attackDamageBonus=ref(0),attackSurprise=ref(false),category=ref(''),weaponSearch=ref('');
watch(attackerId,()=>{obstacleId.value='';obstacleKnown.value=false;obstacleBlocks.value=false;});
const attacker=computed(()=>attackers.value.find(a=>a.id===attackerId.value));
const categories=computed(()=>[...new Set<string>((attacker.value?.options??[]).map((w:any)=>w.group??'Autres'))].sort((a,b)=>a.localeCompare(b,'fr')));
const options=computed(()=>(attacker.value?.options??[]).filter((w:any)=>(!category.value||w.group===category.value)&&w.label.toLocaleLowerCase('fr').includes(weaponSearch.value.toLocaleLowerCase('fr'))));
const option=computed(()=>attacker.value?.options.find((o:any)=>o.id===optionId.value));
watch(attackerId,()=>{attackEdge.value=false;attackPowerId.value='';attackContextConfirmed.value=false;optionId.value='';category.value='';weaponSearch.value='';});

watch([optionId,attackPowerId],()=>{attackContextConfirmed.value=false;});
watch(()=>[attackerId.value,attackTarget.value,optionId.value].join('|'),()=>{pursuesImpulse.value=false;attackDistance.value=null;areaDistance.value=null;additionalTargets.value=[];targetDistances.value={};attackContextConfirmed.value=false;});

watch(()=>[optionId.value,option.value?.requiresAdjudication,option.value?.modeChangeCost,option.value?.mode].join('|'),()=>{attackContextConfirmed.value=false;attackDamageVector.value='';});
const launchReady=computed(()=>!busy.value&&attacker.value?.ready!==false&&!!option.value&&option.value.remaining!==0&&!!attackTarget.value&&(option.value?.attackMode!=='foudre'||typeof attackDistance.value==='number'&&Number.isFinite(attackDistance.value)&&attackDistance.value>=0&&attackDistance.value<=(option.value?.areaRadius??20)&&(option.value?.areaRadius?typeof areaDistance.value==='number'&&areaDistance.value>=0&&areaDistance.value<=20:true)&&additionalTargets.value.every(id=>Number.isFinite(targetDistances.value[id])&&targetDistances.value[id]>=0&&targetDistances.value[id]<=(option.value?.areaRadius??20)))&&!attackPower.value?.used&&(!attackConditions.value.length||attackContextConfirmed.value)&&(!attackRulingRequired.value||props.room.canManage)&&(!option.value?.requiresAdjudication||damageVectors.some(v=>v.id===attackDamageVector.value)));
function launchPayload(){return {attackerId:attackerId.value,optionId:optionId.value,targetId:attackTarget.value,bonus:attackBonus.value,bonusDamage:attackDamageBonus.value,surprise:attackSurprise.value,...(option.value?.attackMode==='foudre'?{distance:attackDistance.value,areaDistance:areaDistance.value,targetNatureConfirmed:attackContextConfirmed.value,targets:[{id:attackTarget.value,distance:attackDistance.value},...additionalTargets.value.filter(id=>id!==attackTarget.value).map(id=>({id,distance:targetDistances.value[id]}))].map(t=>({...t,kind:'creature',immaterial:!!option.value.requiresOccultTarget,exposed:!!option.value.requiresExposedComponent,perceived:!!option.value.requiresPerceivedTarget}))}:{}),intensiveUse:intensiveUse.value,matterSpent:matterSpent.value,pursuesImpulse:pursuesImpulse.value,...(attackEdge.value?{edge:true}:{}),...(attackPowerId.value?{powerId:attackPowerId.value}:{}),...(option.value?.requiresAdjudication?{damageType:attackDamageVector.value}:{}),contextConfirmed:attackContextConfirmed.value||pursuesImpulse.value};}
function launchAttack(){if(launchReady.value)void send('launch',launchPayload());}

const eventId=ref(''),targetId=ref(''),damage=ref<number|null>(null),bonusDamage=ref(0),penetration=ref(0),damageType=ref('melee'),attackMode=ref('melee'),surprise=ref(false);
const drafts=ref<Record<string,any>>({});let alive=true,timer:ReturnType<typeof setInterval>;
const rolls=computed(()=>props.room.events.filter((e:any)=>['roll','gm-roll'].includes(e.kind)&&e.payload.total!==undefined));
const targets=computed(()=>[...props.room.characters,...props.room.combatants]);
watch(weaponId,()=>{const w=weapons.value.find(w=>w.id===weaponId.value);if(w){damage.value=w.damage;penetration.value=Number(/Perforant\s+(\d+)/i.exec(w.properties)?.[1]??0);damageType.value=weaponMechanics(w).damageType;attackMode.value=weaponMechanics(w).attackMode;}});
watch(eventId,()=>{const p=rolls.value.find((e:any)=>e.id===eventId.value)?.payload;damage.value=p?.damage??null;penetration.value=p?.penetration??0;damageType.value=p?.damageType??'melee';attackMode.value=p?.attackMode??(p?.damageType==='balistique'?'ranged':'melee');});
async function load(){if(!alive||document.visibilityState==='hidden')return;try{const r=await api<any>(endpoint);if(!alive)return;pending.value=r.pending;arcOffers.value=r.arcOffers??[];for(const a of arcOffers.value)arcDrafts.value[a.id]??={targetId:'',distance:null,confirmed:false};lightningReactions.value=r.lightningReactions??[];for(const a of lightningReactions.value)allyLightningDrafts.value[a.id]??={actorId:'',distance:null,destination:'',ally:false,confirmed:false,safe:false,edge:false,pursuesImpulse:false};reactable.value=r.reactable??[];counterAttacks.value=r.counterAttacks??[];for(const a of reactable.value)reactionDrafts.value[a.id]??={key:'',distance:0,confirmed:false,ally:false,nearby:false,edge:false,pursuesImpulse:false};for(const a of counterAttacks.value)counterDrafts.value[a.attackId]??={optionId:'',confirmed:false};weapons.value=r.weapons??[];attackers.value=r.attackers??[];if(!attackers.value.some(a=>a.id===attackerId.value)&&attackers.value.length)attackerId.value=attackers.value[0].id;for(const a of r.pending)drafts.value[a.id]??={protectionIds:[],material:['melee','balistique','antichoc'].includes(a.damageType),armor:a.target.armor,extraArmor:0,extraReduction:0,bonus:0,defenseOverride:0,edge:false,defensePowerId:'',defenseContextConfirmed:false,neuroProgramId:'',damagePowerId:'',damageContextConfirmed:false,auraSpend:0,sacrificePrograms:[],supernaturalConfirmed:false,foudreDefenseKind:'',foudreDefenseConfirmed:false,paratonnerreDestination:'',paratonnerreSafe:false,paratonnerreConfirmed:false,paratonnerreEdge:false,electricProtectionNote:'',electricProtectionConfirmed:false,magicalProtection:0,guardToken:false,ablativeHostId:'',ablativeMountedConfirmed:false,pursuesImpulse:false,finVeritable:false,fleauConfirmed:false,destructionConditionsConfirmed:false,finNote:'',erodeProtection:false,erosionLayerId:'',erosionAmount:0,erosionMaterial:true,erosionConfirmed:false};}catch{if(alive){pending.value=[];error.value='Impossible de charger les attaques en attente.';}}}
async function send(action:string,extra:any){if(busy.value)return;if(request.value){error.value='Réessaie l’action non confirmée.';return;}request.value={action,requestId:crypto.randomUUID(),...extra};await retry();}
async function retry(){if(busy.value||!request.value)return;busy.value=true;error.value='';try{const response=await api<any>(endpoint,{method:'POST',body:JSON.stringify(request.value)});if(response.result)reactionNotice.value=response.result.label+(response.result.total!=null?` · ${response.result.modifier} + ${response.result.dice.join(' + ')} = ${response.result.total}${response.result.narrativeFailure?' · échec narratif':''}`:' · cible de l’attaque changée');if(response.result?.success!==undefined)reactionNotice.value+=response.result.success?' · décharge détournée':' · opposition échouée';request.value=null;attackEdge.value=false;await load();emit('changed');}catch(e){error.value=e instanceof ApiError&&lightningErrors[e.message]?lightningErrors[e.message]:e instanceof ApiError&&e.status===409?'Cette attaque a déjà changé ou a déjà été traitée.':e instanceof ApiError&&e.message==='insufficient_edge'?'Pas assez d’Edge pour cette dépense.':e instanceof ApiError&&e.message==='defense_power_unavailable'?'Cette défense spéciale est indisponible ou déjà utilisée. Actualise et choisis une autre défense.':e instanceof ApiError&&e.message==='active_defense_unavailable'?'Défense active indisponible : vérifie les PA, l’initiative, la surprise et les blessures.':e instanceof ApiError&&e.message==='attack_unavailable'?'Attaque indisponible : commence le combat, vérifie les PA et les blessures.':e instanceof ApiError&&e.message==='truth_weapon_ruling_required'?'Le MJ doit choisir le type de dégâts de cette arme et confirmer son arbitrage.':e instanceof ApiError&&e.message==='weapon_mode_ruling_required'?'Le MJ doit confirmer que le changement de mode et son coût en PA ont été résolus.':'Action non confirmée. Réessaie.';if(e instanceof ApiError&&e.status<500){request.value=null;await load();}}finally{busy.value=false;}}
function reactionChoice(a:any){const d=reactionDrafts.value[a.id];return a.options.find((o:any)=>o.actorId+'|'+o.id===d?.key);}
function reactionReady(a:any){const d=reactionDrafts.value[a.id],o=reactionChoice(a);return !busy.value&&!request.value&&!!o&&d.confirmed&&d.ally&&(o.range!==null||d.nearby)&&Number.isFinite(d.distance)&&d.distance>=0&&(o.range==='movement'?d.distance<o.movement:typeof o.range==='number'?d.distance<=o.range:true);}
function react(a:any){if(!reactionReady(a))return;const d=reactionDrafts.value[a.id],o=reactionChoice(a);void send('react',{attackId:a.id,expectedTargetId:a.targetId,actorId:o.actorId,actorVersion:o.version,powerId:o.id,distance:d.distance,contextConfirmed:d.confirmed,allyConfirmed:d.ally,nearbyConfirmed:d.nearby,edge:d.edge,pursuesImpulse:d.pursuesImpulse});}
function riposte(a:any){const d=counterDrafts.value[a.attackId];if(!d.optionId||!d.confirmed||busy.value)return;void send('launch',{attackerId:a.actorId,targetId:a.targetId,optionId:d.optionId,riposteAttackId:a.attackId,inReach:true,bonus:0,bonusDamage:0,surprise:false});}
function allyParatonnerre(a:any){const d=allyLightningDrafts.value[a.id],actor=a.options.find((o:any)=>o.actorId===d.actorId);if(!actor)return;void send('paratonnerre',{attackId:a.id,actorId:actor.actorId,actorVersion:actor.version,distance:d.distance,allyConfirmed:d.ally,destination:d.destination,safeDestinationConfirmed:d.safe,contextConfirmed:d.confirmed,edge:d.edge,pursuesImpulse:d.pursuesImpulse});}
function specialDefense(a:any){return a.target.specialDefenses?.find((p:any)=>p.id===drafts.value[a.id]?.defensePowerId);}
function canChooseDefense(a:any){const d=drafts.value[a.id];return a.attackMode!=='foudre'||['physical','occult'].includes(d.foudreDefenseKind)&&d.foudreDefenseConfirmed;}
function paratonnerre(a:any){const d=drafts.value[a.id];if(!a.target.paratonnerre?.available||!d.paratonnerreConfirmed||!d.paratonnerreSafe||!d.paratonnerreDestination.trim())return;void send('paratonnerre',{attackId:a.id,actorVersion:a.target.version,destination:d.paratonnerreDestination,contextConfirmed:d.paratonnerreConfirmed,safeDestinationConfirmed:d.paratonnerreSafe,edge:d.paratonnerreEdge,pursuesImpulse:d.pursuesImpulse});}
function canDefend(a:any){if(!canChooseDefense(a))return false;const d=drafts.value[a.id],special=specialDefense(a);if(a.narrativeFailure)return false;if(special)return special.available&&(!special.context||d.defenseContextConfirmed);return a.target.canDefend&&(!a.surprise||a.target.canSurprised)&&(a.damageType!=='neuro'||!!d.neuroProgramId);}
function damagePower(a:any){return a.target.damagePowers?.find((p:any)=>p.id===drafts.value[a.id]?.damagePowerId);}
function powerReduction(a:any){const p=damagePower(a);if(!p||p.context&&!drafts.value[a.id].damageContextConfirmed)return 0;return (p.effects??[]).filter((e:any)=>e.kind==='reduction').reduce((n:number,e:any)=>n+Number(e.amount),0);}
function defensePayload(a:any,active:boolean){const d=drafts.value[a.id];return {attackId:a.id,active,bonus:d.bonus,pursuesImpulse:d.pursuesImpulse,contextConfirmed:d.pursuesImpulse===true,...(a.attackMode==='foudre'?{defenseKind:d.foudreDefenseKind,contextConfirmed:d.foudreDefenseConfirmed}:{}),...(active&&d.defensePowerId?{defensePowerId:d.defensePowerId,contextConfirmed:d.defenseContextConfirmed}:{}),...(active&&d.neuroProgramId?{neuroProgramId:d.neuroProgramId}:{}),...(active&&d.edge?{edge:true}:{})};}
function resolvePayload(a:any){const d=drafts.value[a.id];return {attackId:a.id,protectionIds:d.protectionIds,material:a.attackMode==='foudre'||a.damageType==='neuro'?false:d.material,armor:d.armor,extraArmor:d.extraArmor,extraReduction:d.extraReduction,defenseOverride:d.defenseOverride,guardToken:d.guardToken,pursuesImpulse:d.pursuesImpulse,contextConfirmed:d.pursuesImpulse===true,ablativeHostId:d.ablativeHostId,ablativeMountedConfirmed:d.ablativeMountedConfirmed,...(props.room.canManage?{finVeritable:d.finVeritable,fleauConfirmed:d.fleauConfirmed,destructionConditionsConfirmed:d.destructionConditionsConfirmed,finNote:d.finNote,magicalProtection:d.magicalProtection,erodeProtection:d.erodeProtection,erosionLayerId:d.erosionLayerId,erosionAmount:d.erosionAmount,erosionMaterial:d.erosionMaterial,erosionConfirmed:d.erosionConfirmed}:{}),...(a.attackMode==='foudre'&&props.room.canManage?{electricProtectionNote:d.electricProtectionNote,electricProtectionConfirmed:d.electricProtectionConfirmed}:{}),...(d.damagePowerId?{damagePowerId:d.damagePowerId,contextConfirmed:d.damageContextConfirmed}:{}),auraSpend:a.damageType==='occulte'?d.auraSpend:0,sacrificePrograms:a.damageType==='neuro'?d.sacrificePrograms:[],...(props.room.canManage?{supernaturalConfirmed:d.supernaturalConfirmed}:{})};}
function canResolve(a:any){const d=drafts.value[a.id];if(d.finVeritable&&(!d.fleauConfirmed||!d.destructionConditionsConfirmed||!d.finNote.trim()||a.target.hp-preview(a).damage>a.target.death))return false;if(a.attackMode==='foudre'&&d.extraReduction>0&&(!props.room.canManage||!d.electricProtectionConfirmed||!d.electricProtectionNote.trim()))return false;const p=damagePower(a);return !(a.defense.narrativeFailure&&!props.room.canManage)&&(!p||!p.used&&(!p.context||drafts.value[a.id].damageContextConfirmed));}

function preview(a:any):any{const d=drafts.value[a.id],items=(a.target.protections??[]).filter((p:any)=>d.protectionIds.includes(p.id)),defense=Math.max(a.defense?.narrativeFailure?d.defenseOverride:a.defense?.total??a.target.defense,a.reactionDefense??0),vector=a.occultTarget?'occulte':a.damageType;
 const armor=a.attackMode==='foudre'||a.damageType==='neuro'||!d.material?0:Number(d.armor)+Number(d.extraArmor)+Math.max(0,...items.map((p:any)=>p.armor))+Math.max(a.target.bodyArmor??0,...items.map((p:any)=>p.body));
 let reduction=Number(d.extraReduction)+(a.target.reductions?.[vector]??0)+Math.max(0,...items.map((p:any)=>p.reductions?.[vector]??0))+[...new Map(items.map((p:any)=>[p.itemId??p.id,p])).values()].reduce((n:number,p:any)=>n+(p.additive?.[vector]??0),0)+powerReduction(a)+(a.damageType==='neuro'?3*d.sacrificePrograms.length:0)+(a.damageType==='occulte'?Number(d.auraSpend)*(a.target.aura?.egidePerAura??0):0);
 if(a.attackMode==='foudre'){if(a.lightning?.ignoreMagicProtection)reduction=Math.max(0,reduction-Number(d.magicalProtection));if(a.lightning?.halfElectricProtection)reduction=Math.floor(reduction/2);}
 const supernatural=a.attackMode==='foudre'||a.damageType==='occulte'||props.room.canManage&&d.supernaturalConfirmed,hit=!a.narrativeFailure&&a.total>defense;
 const mounted=items.some((p:any)=>(p.itemId??p.sourceId??p.id)==='modules-d-armure-plaques-ablatives'&&(p.ablativeRemaining??0)>0)&&d.ablativeMountedConfirmed&&items.some((p:any)=>p.id===d.ablativeHostId&&((p.armor??0)>0||Object.values(p.reductions??{}).some((r:any)=>r>0)));if(mounted&&d.material&&a.attackMode!=='foudre'&&a.damageType!=='neuro')reduction+=1;
 if(a.target.guard&&hit&&supernatural)reduction+=6;if(items.some((p:any)=>p.sourceId==='verite-24-brigandine-de-garde')&&a.target.guardItems?.brigandine?.available&&hit&&supernatural)reduction+=3;if(d.guardToken&&hit&&supernatural)reduction+=2;
 const calc=damageCalculation({...a,bonusDamage:a.bonusDamage-(d.erodeProtection?2:0)},defense,armor,reduction);if(a.electricDiversion?.success){calc.hit=false;calc.damage=0;calc.alteration=false;}return calc;
}

async function prepareAttack(id:string,rollId=''){category.value='';weaponSearch.value='';attackerId.value=id;await nextTick();optionId.value=attacker.value?.options.some((o:any)=>o.id===rollId)?rollId:'';document.querySelector('.combat-resolution')?.scrollIntoView({behavior:'smooth',block:'start'});}
defineExpose({prepareAttack});
onMounted(()=>{void load();timer=setInterval(()=>void load(),3000);});onUnmounted(()=>{alive=false;clearInterval(timer);});
</script>
<template>
<section class="combat-resolution" aria-label="Résolution des attaques">
 <h2>Attaques & défenses</h2><details v-if="room.canManage&&attacker?.frenzy?.active&&attacker.frenzy.fearSuppressed&&!attacker.frenzy.lucid"><summary>Frénésie · un proche fait obstacle</summary><p>{{attacker.name}} · {{attacker.frenzy.impulse}}</p><p v-if="obstacleError" role="alert">{{obstacleError}}</p><label>Proche concerné<select v-model="obstacleId"><option value="">Choisir…</option><option v-for="t in targets.filter((t:any)=>t.id!==attackerId)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label class="check"><input v-model="obstacleKnown" type="checkbox" /> Le personnage reconnaît habituellement ce proche.</label><label class="check"><input v-model="obstacleBlocks" type="checkbox" /> Ce proche fait réellement obstacle à son impulsion.</label><button :disabled="busy||!obstacleId||!obstacleKnown||!obstacleBlocks" @click="testObstacle">Reconnaître ce proche · DD 15 · 0 PA</button></details><p v-if="error" role="alert">{{ error }} <button v-if="request" :disabled="busy" @click="retry">Réessayer cette action</button></p>
 <p v-if="attacker&&!attacker.options.length">Aucune attaque chiffrée disponible : complète le profil de cette créature avant de lancer une attaque.</p><form v-if="attackers.length" @submit.prevent="launchAttack"><h3>Lancer une attaque</h3><p v-if="attacker?.ready===false" role="status">{{attacker.initiativePending?'Lance d’abord ton initiative.':'Aucune attaque disponible : vérifie les PA, les blessures et la transformation en cours.'}}</p><div class="combat-fields"><label>Attaquant<select v-model="attackerId" aria-label="Attaquant" required><option v-for="a in attackers" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Catégorie d’arme<select v-model="category" aria-label="Catégorie d’arme"><option value="">Toutes les catégories</option><option v-for="c in categories" :key="c" :value="c">{{c}}</option></select></label><label>Rechercher une arme<input v-model="weaponSearch" type="search" /></label><label>Arme / attaque<select v-model="optionId" aria-label="Arme / attaque" required><option value="">Choisir…</option><optgroup v-for="group in categories.filter(c=>options.some((o:any)=>(o.group??'Autres')===c))" :key="group" :label="group"><option v-for="w in options.filter((o:any)=>(o.group??'Autres')===group)" :key="w.id" :value="w.id" :disabled="w.remaining===0">{{w.label}} · {{w.damageMode==='margin'?'DGT = marge':'DGT '+w.damage}}<template v-if="w.capacity!=null"> · {{w.remaining}} / {{w.capacity}} charges{{w.remaining===0?' · vide':''}}</template></option></optgroup></select></label><label v-if="attacker?.powers?.length">Capacité pour l’attaque<select v-model="attackPowerId" aria-label="Capacité pour l’attaque"><option value="">Attaque ordinaire</option><option v-for="p in attacker.powers" :key="p.id" :value="p.id" :disabled="p.used">{{p.name}}<template v-if="p.limit"> · {{frequency(p.limit)}}</template>{{p.used?' · déjà utilisée':''}}</option></select></label><label>Cible de l’attaque<select v-model="attackTarget" aria-label="Cible de l’attaque" required><option value="">Choisir avant de lancer…</option><option v-for="t in targets.filter((t:any)=>t.id!==attackerId)" :key="t.id" :value="t.id">{{t.name}} · {{t.health}}</option></select></label><label v-if="option?.attackMode==='foudre'">Distance réelle de la cible (m)<input v-model.number="attackDistance" @input="attackContextConfirmed=false" aria-label="Distance de la cible de Foudre" type="number" min="0" :max="option?.areaRadius??20" step="0.1" required /></label><label>Bonus au jet<input v-model.number="attackBonus" type="number" min="-100" max="100" /></label><label>Bonus aux dégâts<input v-model.number="attackDamageBonus" type="number" min="-100" max="100" /></label><label v-if="attacker?.edge!=null" class="check"><input v-model="attackEdge" type="checkbox" :disabled="busy||attacker.edge<1" /> Forcer le Destin · 1 Edge ({{attacker.edge}} disponibles)</label><label class="check"><input v-model="attackSurprise" type="checkbox" /> Cible surprise</label></div><p v-if="option?.capacity!=null" class="ammo-status" role="status">Chargeur : {{option.remaining}} / {{option.capacity}} charges. <span v-if="option.remaining===0">Recharge cette arme depuis ta fiche avant de tirer.</span><span v-else>Cette attaque de Tir simple consomme une charge.</span></p><div v-if="attackPower" class="power-rule"><strong>{{attackPower.name}}</strong><p>{{(attackPower.effects??[]).map(effectText).join(' · ')}}<template v-if="attackPower.cost"> · {{attackPower.cost}} PA supplémentaires</template></p></div><template v-if="option?.areaRadius||option?.maxTargets"><label v-if="option.areaRadius">Distance du centre de la zone (m)<input v-model.number="areaDistance" @input="attackContextConfirmed=false" aria-label="Distance du centre de Foudre" type="number" min="0" max="20" /></label><details><summary>Cibles supplémentaires{{option.maxTargets?' · '+option.maxTargets+' au total':''}}</summary><template v-for="t in targets.filter((t:any)=>t.id!==attackerId&&t.id!==attackTarget)" :key="t.id"><label class="check"><input v-model="additionalTargets" @change="attackContextConfirmed=false" type="checkbox" :value="t.id" :disabled="!additionalTargets.includes(t.id)&&option.maxTargets&&additionalTargets.length>=option.maxTargets-1" /> {{t.name}}</label><label v-if="additionalTargets.includes(t.id)">Distance {{option.areaRadius?'au centre':'du lanceur'}} (m)<input v-model.number="targetDistances[t.id]" @input="attackContextConfirmed=false" type="number" min="0" :max="option.areaRadius??20" required /></label></template></details></template><p v-if="option?.requiresOccultTarget||option?.requiresExposedComponent">Le MJ doit confirmer les cibles immatérielles, réellement perçues et les composantes exposées.</p><details v-if="option?.sourceId"><summary>Régime et réserve de cette arme</summary><p v-if="option.modeChangeCost">Un changement vers {{option.mode}} ajoute {{option.modeChangeCost}} PA ; un régime déjà actif ne paie pas de nouveau ce coût.</p><label v-if="option.sourceId==='verite-26-helios-pr-8'" class="check"><input v-model="intensiveUse" type="checkbox" /> Usage intensif · refroidissement jusqu’à la prochaine activation</label><label v-if="option.sourceId==='verite-26-custodian-ar-9'&&option.mode==='perforant'">Matière réellement consommée<input v-model.number="matterSpent" type="number" min="2" max="10000" /></label></details><label v-if="attacker?.frenzy?.impulseRequired" class="check"><input v-model="pursuesImpulse" type="checkbox" /> Cette attaque poursuit mon impulsion de Frénésie.</label>
 <div v-if="attackRulingRequired" class="weapon-ruling"><p>{{option.notes}}</p><p v-if="!room.canManage" role="status">Demande l’arbitrage du MJ avant cette attaque : {{option.requiresAdjudication?'le type de dégâts reste à préciser.':'le changement de mode et son coût en PA doivent être résolus.'}}</p><label v-if="room.canManage&&option.requiresAdjudication">MJ · type de dégâts retenu<select v-model="attackDamageVector" aria-label="Type de dégâts arbitré par le MJ" required><option value="">Choisir le type après arbitrage…</option><option v-for="vector in damageVectors" :key="vector.id" :value="vector.id">{{vector.label}}</option></select></label></div><label v-if="attackConditions.length&&(!attackRulingRequired||room.canManage)" class="check attack-context"><input v-model="attackContextConfirmed" type="checkbox" /> Je confirme les conditions : {{attackConditions.join(' · ')}}</label><p v-if="option"><template v-if="option.components?.attributeName">{{option.components.attributeName}} {{option.components.attribute}} + {{option.components.skillName}} {{option.components.rank}} + bonus de fiche {{option.components.bonus??0}}</template><template v-else>Score du profil {{option.modifier}}</template> + bonus {{attackBonus}} + {{attackEdge?'20 (Edge)':'d10'}} · {{option.damageMode==='margin'?'Dégâts = marge du jet':option.damage+' dégâts de base'}} · {{option.penetration}} perforant</p><button :disabled="!launchReady">Lancer l’attaque · {{(option?.actionCost??1)+(attackPower?.cost??0)}} PA<template v-if="option?.modeChangeCost"> + {{option.modeChangeCost}} PA si changement de régime</template></button><small>{{room.canManage?'Catalogue trié par catégorie et par nom.':'Tes armes possédées, attaques naturelles et capacités disponibles sont proposées.'}} La cible reçoit directement la demande de défense.</small></form>
 <details v-if="room.canManage"><summary>Diriger un jet d’attaque vers une cible</summary><form @submit.prevent="send('attack',{eventId,targetId,damage,bonusDamage,penetration,damageType,attackMode,surprise})"><div class="combat-fields">
 <label>Jet d’attaque<select v-model="eventId" required><option value="">Choisir un jet du journal…</option><option v-for="e in rolls" :key="e.id" :value="e.id">{{ e.characterName??e.payload.characterName??'MJ' }} · {{ e.payload.label }} → {{ e.payload.total }}</option></select></label>
 <label>Cible<select v-model="targetId" required><option value="">Choisir…</option><option v-for="c in targets" :key="c.id" :value="c.id">{{ c.name }}</option></select></label>
 <label>Arme du catalogue (facultatif)<select v-model="weaponId"><option value="">Profil du jet ou saisie</option><option v-for="w in weapons" :key="w.id" :value="w.id">{{ w.name }} · DGT {{ w.damage }}</option></select></label><label>Dégâts de l’arme<input v-model.number="damage" type="number" min="0" max="100" required /></label><label>Bonus de dégâts<input v-model.number="bonusDamage" type="number" min="-100" max="100" required /></label><label>Perforant<input v-model.number="penetration" type="number" min="0" max="100" required /></label><label>Calcul des dégâts<select v-model="attackMode" aria-label="Calcul des dégâts"><option value="melee">Mêlée / Pugilat · marge + DGT</option><option value="ranged">Tir · paliers de marge</option><option value="foudre">Foudre · marge + DGT, protection électrique</option><option value="margin">Marge seule · Neuro</option><option value="fixed">DGT fixes · effet particulier</option></select></label><label>Type de dégâts<select v-model="damageType"><option value="melee">Mêlée</option><option value="balistique">Balistique</option><option value="antichoc">Antichoc</option><option value="feu">Feu</option><option value="froid">Froid</option><option value="electricite">Électricité</option><option value="chimique">Chimique</option><option value="occulte">Occulte</option><option value="neuro">Neuro</option></select></label>
 <label class="check"><input v-model="surprise" type="checkbox" /> Surprise : pas de défense active</label></div><button :disabled="busy||!eventId||!targetId||damage===null">Proposer l’attaque au défenseur</button><small>Vérifie les propriétés de l’arme et les bonus de dégâts avant d’envoyer. Le joueur ciblé peut choisir sa défense ici ; le MJ peut aussi la résoudre.</small></form></details>
 <p v-if="reactionNotice" role="status">{{reactionNotice}}</p>
 <article v-for="a in reactable" :key="'react-'+a.id" class="reaction-card">
  <h3>Réagir pour protéger {{a.targetName}}</h3><p>{{a.attacker}} cible cet allié. L’intervention doit précéder son choix de défense.</p>
  <div class="combat-fields"><label>Intervenant / capacité<select v-model="reactionDrafts[a.id].key" @change="reactionDrafts[a.id].confirmed=false;reactionDrafts[a.id].ally=false;reactionDrafts[a.id].nearby=false" :aria-label="`Interposition pour ${a.targetName}`"><option value="">Choisir…</option><option v-for="o in a.options" :key="o.actorId+'|'+o.id" :value="o.actorId+'|'+o.id">{{o.actorName}} · {{o.name}} · 1 PA{{o.limit?' · 1/round':''}}</option></select></label><label>Distance réelle jusqu’à l’allié (m)<input v-model.number="reactionDrafts[a.id].distance" @input="reactionDrafts[a.id].confirmed=false" type="number" min="0" max="10000" step="0.1" /></label></div>
  <template v-if="reactionChoice(a)"><p v-if="reactionChoice(a).range==='movement'">La distance doit être inférieure au Déplacement : {{reactionChoice(a).movement}} m.</p><p v-else-if="reactionChoice(a).range!=null">Portée maximale : {{reactionChoice(a).range}} m.</p><p>{{reactionChoice(a).kind==='redirect'?'Tu deviens la cible ; ton propre choix de défense et tes protections serviront ensuite.':'Jet Agilité + Esquive : la meilleure défense protège l’allié, qui conserve ses propres protections.'}}</p><label class="check"><input v-model="reactionDrafts[a.id].ally" type="checkbox" /> La cible est réellement un allié.</label><label v-if="reactionChoice(a).range===null" class="check"><input v-model="reactionDrafts[a.id].nearby" type="checkbox" /> L’allié est proche dans la scène.</label><label class="check"><input v-model="reactionDrafts[a.id].confirmed" type="checkbox" /> Je perçois l’attaque et peux physiquement intervenir dans cette trajectoire.</label></template>
  <label v-if="reactionChoice(a)?.frenzy?.impulseRequired" class="check"><input v-model="reactionDrafts[a.id].pursuesImpulse" type="checkbox" /> Cette intervention poursuit mon impulsion de Frénésie.</label><label v-if="reactionChoice(a)?.kind==='defense'" class="check"><input v-model="reactionDrafts[a.id].edge" type="checkbox" /> Forcer ce jet de défense · 1 Edge</label><button :disabled="!reactionReady(a)" @click="react(a)">Intervenir · 1 PA</button>
 </article>
 <article v-for="a in arcOffers" :key="'arc-'+a.id" class="reaction-card"><h3>Arc en chaîne · {{a.actorName}}</h3><p>Premier coup réussi : le même jet {{a.total}} peut rebondir une fois, DGT 5, sans nouveau PA.</p><label>Deuxième cible<select v-model="arcDrafts[a.id].targetId" @change="arcDrafts[a.id].confirmed=false"><option value="">Choisir…</option><option v-for="t in targets.filter((t:any)=>t.id!==a.actorId&&t.id!==a.firstTargetId)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Distance du rebond (m)<input v-model.number="arcDrafts[a.id].distance" @input="arcDrafts[a.id].confirmed=false" type="number" min="0" max="3" /></label><label class="check"><input v-model="arcDrafts[a.id].confirmed" type="checkbox" /> La seconde cible est réellement à 3 m maximum de la première.</label><button :disabled="busy||!arcDrafts[a.id].targetId||arcDrafts[a.id].distance===null||arcDrafts[a.id].distance<0||arcDrafts[a.id].distance>3||!arcDrafts[a.id].confirmed" @click="send('lightning-arc',{attackId:a.id,actorVersion:a.version,targetId:arcDrafts[a.id].targetId,distance:arcDrafts[a.id].distance,contextConfirmed:arcDrafts[a.id].confirmed})">Déclencher le rebond · 0 PA</button></article>
 <article v-for="a in lightningReactions" :key="'ally-lightning-'+a.id" class="reaction-card"><h3>Paratonnerre · protéger {{a.targetName}}</h3>
 <template v-if="a.electricDiversion"><p>{{a.electricDiversion.total}} contre {{a.total}} · opposition échouée</p><button v-if="!a.electricDiversion.edgeForced&&a.edge>0" @click="send('paratonnerre-force',{attackId:a.id,actorId:a.electricDiversion.actorId,actorVersion:a.actorVersion,allyConfirmed:true,distance:0})">Forcer ce Paratonnerre · 1 Edge</button></template>
 <template v-else><label>Intervenant<select v-model="allyLightningDrafts[a.id].actorId" @change="allyLightningDrafts[a.id].confirmed=false"><option value="">Choisir…</option><option v-for="o in a.options" :key="o.actorId" :value="o.actorId">{{o.actorName}}</option></select></label><label>Distance jusqu’à l’allié (m)<input v-model.number="allyLightningDrafts[a.id].distance" @input="allyLightningDrafts[a.id].confirmed=false" type="number" min="0" max="5" step="0.1" /></label><label v-if="a.options.find((o:any)=>o.actorId===allyLightningDrafts[a.id].actorId)?.frenzy?.impulseRequired" class="check"><input v-model="allyLightningDrafts[a.id].pursuesImpulse" type="checkbox" /> Cette réaction poursuit mon impulsion de Frénésie.</label><label>Conducteur ou zone sûre<input v-model="allyLightningDrafts[a.id].destination" @input="allyLightningDrafts[a.id].safe=false" maxlength="200" /></label><label class="check"><input v-model="allyLightningDrafts[a.id].ally" type="checkbox" /> C’est un allié à 5 m maximum.</label><label class="check"><input v-model="allyLightningDrafts[a.id].safe" type="checkbox" /> La destination peut recevoir la décharge.</label><label class="check"><input v-model="allyLightningDrafts[a.id].confirmed" type="checkbox" /> Je perçois cette décharge et peux intervenir.</label><label class="check"><input v-model="allyLightningDrafts[a.id].edge" type="checkbox" /> Forcer ce jet · 1 Edge</label><button :disabled="busy||!allyLightningDrafts[a.id].actorId||allyLightningDrafts[a.id].distance===null||allyLightningDrafts[a.id].distance<0||allyLightningDrafts[a.id].distance>5||!allyLightningDrafts[a.id].destination.trim()||!allyLightningDrafts[a.id].ally||!allyLightningDrafts[a.id].safe||!allyLightningDrafts[a.id].confirmed" @click="allyParatonnerre(a)">Protéger l’allié · 1 PA</button></template></article>
 <article v-for="a in counterAttacks" :key="'counter-'+a.attackId" class="reaction-card"><h3>Riposte d’Ashorn · {{a.actorName}} → {{a.targetName}}</h3><p>Défense active réussie. Une attaque normale de Mêlée ou Pugilat, sans PA supplémentaire, une fois par scène. Lance-la avant de résoudre l’attaque initiale.</p><label>Arme de riposte<select v-model="counterDrafts[a.attackId].optionId" @change="counterDrafts[a.attackId].confirmed=false" aria-label="Arme de riposte"><option value="">Choisir…</option><option v-for="o in a.options" :key="o.id" :value="o.id">{{o.label}} · DGT {{o.damage}}</option></select></label><label class="check"><input v-model="counterDrafts[a.attackId].confirmed" type="checkbox" /> Cet agresseur est réellement à portée de cette attaque.</label><button :disabled="busy||!!request||!counterDrafts[a.attackId].optionId||!counterDrafts[a.attackId].confirmed" @click="riposte(a)">Lancer la riposte · 0 PA supplémentaire</button></article>
 <p v-if="!pending.length">Aucune attaque en attente de défense.</p>
 <article v-for="a in pending" :key="a.id" class="pending-attack"><h3>{{ a.attacker }} → {{ a.target.name }} · Attaque {{ a.total }}</h3><p>{{a.attackMode==='margin'?'DGT = marge':'DGT '+a.damage}} + bonus {{ a.bonusDamage }} · {{ a.damageType }} · Perforant {{ a.penetration }}</p><p v-if="a.reactionDefense!=null">Interposition doctrinale : Défense {{a.reactionDefense}}, retenue si supérieure à celle de la cible.</p><p v-if="a.guardianBonus">Riposte du Gardien : +{{a.guardianBonus}} contre cet agresseur, déjà inclus dans le total.</p><strong v-if="a.narrativeFailure">Échec narratif de l’attaque : aucun dégât.</strong>
 <p v-if="a.attackMode==='foudre'">Foudre : marge + DGT, sans paliers de Tir ni Armure conventionnelle. La défense et la protection doivent être pertinentes pour cette manifestation.</p>
 <fieldset v-if="a.target.paratonnerre||a.electricDiversion" class="lightning-reaction" :disabled="busy||!!request"><legend>Paratonnerre · {{a.target.name}}</legend>
 <p>Protège cette cible : Volonté + Maîtrise spirituelle + d10e, 1 PA, une fois par round. Choisis avant la défense ordinaire. Aucun renvoi automatique vers un adversaire.</p>
 <template v-if="a.electricDiversion"><p>{{a.electricDiversion.modifier}} + {{a.electricDiversion.dice?.join(' + ')}} = {{a.electricDiversion.total}} contre {{a.total}} · {{a.electricDiversion.success?'décharge détournée, aucun dégât':'opposition échouée'}}<span v-if="a.electricDiversion.narrativeFailure"> · échec narratif</span></p><button v-if="!a.defense&&!a.electricDiversion.success&&!a.electricDiversion.edgeForced&&a.target.edge>0" @click="send('paratonnerre-force',{attackId:a.id,actorVersion:a.target.version})">Forcer ce Paratonnerre · 1 Edge</button></template>
 <template v-else-if="a.target.paratonnerre?.available"><label>Conducteur ou zone valide proche<input v-model="drafts[a.id].paratonnerreDestination" @input="drafts[a.id].paratonnerreSafe=false;drafts[a.id].paratonnerreConfirmed=false" aria-label="Destination de Paratonnerre" maxlength="200" /></label><label class="check"><input v-model="drafts[a.id].paratonnerreSafe" type="checkbox" /> Cette destination peut réellement recevoir la décharge.</label><label class="check"><input v-model="drafts[a.id].paratonnerreConfirmed" type="checkbox" /> Je perçois cette manifestation électrique et peux intervenir.</label><label class="check"><input v-model="drafts[a.id].paratonnerreEdge" type="checkbox" :disabled="a.target.edge<1" /> Forcer ce Jet de Foudre · 1 Edge</label><button :disabled="!drafts[a.id].paratonnerreDestination.trim()||!drafts[a.id].paratonnerreSafe||!drafts[a.id].paratonnerreConfirmed" @click="paratonnerre(a)">Détourner la décharge · 1 PA</button></template><p v-else-if="!a.electricDiversion">Réaction indisponible : vérifie le quota, les PA, la Surprise et la fenêtre de réaction.</p>
 </fieldset>
 <div v-if="!a.defense&&a.attackMode==='foudre'" class="foudre-defense"><label>Défense pertinente contre cette Foudre<select v-model="drafts[a.id].foudreDefenseKind" @change="drafts[a.id].foudreDefenseConfirmed=false" aria-label="Défense pertinente contre la Foudre"><option value="">Choisir avec le MJ…</option><option value="physical">Physique · Esquive</option><option value="occult">Occulte · Force mentale</option></select></label><label class="check"><input v-model="drafts[a.id].foudreDefenseConfirmed" type="checkbox" /> Cette défense est pertinente pour la manifestation, après arbitrage avec le MJ.</label></div>
 <label v-if="a.target.frenzy?.impulseRequired" class="check"><input v-model="drafts[a.id].pursuesImpulse" type="checkbox" /> Cette réaction poursuit mon impulsion de Frénésie.</label>
 <div v-if="!a.defense" class="combat-fields"><label v-if="a.target.specialDefenses?.length">Capacité de défense<select v-model="drafts[a.id].defensePowerId" @change="drafts[a.id].defenseContextConfirmed=false" :aria-label="`Capacité de défense de ${a.target.name}`"><option value="">Défense ordinaire · 1 PA</option><option v-for="p in a.target.specialDefenses" :key="p.id" :value="p.id" :disabled="!p.available">{{p.name}} · {{p.cost}} PA · +{{p.bonus}}{{p.limit?' · '+frequency(p.limit):''}}{{p.used?' · déjà utilisée':''}}{{p.surprise?' · même Surpris':''}}</option></select></label><label v-if="specialDefense(a)?.context" class="check"><input v-model="drafts[a.id].defenseContextConfirmed" type="checkbox" /> Je confirme : {{specialDefense(a).context}}</label><label v-if="a.damageType==='neuro'&&a.target.neuroPrograms?.length">Programme de Défense Neuro<select v-model="drafts[a.id].neuroProgramId" :aria-label="`Programme de Défense Neuro de ${a.target.name}`"><option value="">Choisir un programme chargé…</option><option v-for="p in a.target.neuroPrograms" :key="p.id" :value="p.id" :disabled="p.available===false">{{p.label??p.name}} · +{{p.bonus}} Défense Neuro</option></select></label><p v-if="specialDefense(a)">{{specialDefense(a).name}} : +{{specialDefense(a).bonus}} appliqué automatiquement. Le coût et l’éventuel usage limité sont consommés au lancer, même en cas d’échec narratif. {{specialDefense(a).surprise?'La Surprise n’interdit pas cette réaction.':'Ne permet pas de réagir en Surprise.'}}</p><label>Bonus de défense<input v-model.number="drafts[a.id].bonus" type="number" min="-100" max="100" /></label><button :disabled="busy||!canChooseDefense(a)" @click="send('defend',defensePayload(a,false))">Défense passive · 0 PA</button><button :disabled="busy||!canDefend(a)" @click="send('defend',defensePayload(a,true))">Défense active · {{specialDefense(a)?.cost??1}} PA · {{drafts[a.id].edge?'20 (Edge)':'d10'}}</button><label v-if="a.target.edge!=null" class="check"><input v-model="drafts[a.id].edge" type="checkbox" :disabled="busy||a.target.edge<1" /> Forcer la défense active · 1 Edge ({{a.target.edge}} disponibles)</label><span>{{ a.target.pa }} PA disponibles</span></div>
 <form v-else @submit.prevent="send('resolve',resolvePayload(a))"><details v-if="room.canManage&&a.lightning?.finVeritable"><summary>Fin véritable · destruction définitive</summary><label class="check"><input v-model="drafts[a.id].finVeritable" type="checkbox" /> Appliquer Fin véritable à ce fléau.</label><template v-if="drafts[a.id].finVeritable"><label class="check"><input v-model="drafts[a.id].fleauConfirmed" type="checkbox" /> La cible est bien un fléau ou une engeance concernés.</label><label class="check"><input v-model="drafts[a.id].destructionConditionsConfirmed" type="checkbox" /> Les conditions réelles de sa destruction sont remplies.</label><label>Conditions vérifiées<input v-model="drafts[a.id].finNote" maxlength="400" /></label><p>Seul un impact réellement mortel peut empêcher sa reconstitution.</p></template></details><p v-if="a.defense.defensePowerName">{{a.defense.defensePowerName}} · {{a.defense.paCost}} PA · bonus automatique +{{a.defense.components?.specialBonus}}</p><p>{{ a.defense.label }} : {{ a.defense.modifier }}<template v-if="a.defense.dice"> + {{ a.defense.dice.join(' + ') }}</template> = {{ a.defense.total }}</p>
 <p v-if="a.defense.narrativeFailure" role="alert">Échec narratif de la défense : le MJ doit arbitrer la défense retenue avant application.</p><label v-if="a.defense.narrativeFailure&&room.canManage">Défense retenue après arbitrage<input v-model.number="drafts[a.id].defenseOverride" type="number" min="0" max="1000" required /></label>
 <fieldset v-if="a.target.guard"><legend>Rune de Garde</legend><p>−6 dégâts sur la première atteinte surnaturelle ; la rune s’éteint à cet impact, même si les autres protections annulent déjà les dégâts.</p><label v-if="room.canManage&&a.damageType!=='occulte'&&a.attackMode!=='foudre'" class="check"><input v-model="drafts[a.id].supernaturalConfirmed" type="checkbox" /> Le MJ confirme que cet impact est surnaturel.</label><p v-else-if="a.damageType!=='occulte'&&a.attackMode!=='foudre'">Le MJ doit confirmer le caractère surnaturel pour appliquer la rune à cet impact.</p></fieldset><fieldset><legend>Protections applicables à cet impact</legend><label class="check"><input v-model="drafts[a.id].material" type="checkbox" :disabled="a.damageType==='neuro'||a.attackMode==='foudre'" /> La protection matérielle peut s’interposer contre cet impact</label><p v-if="a.damageType==='neuro'">Les dégâts Neuro ignorent l’Armure physique. Les réductions Neuro restent applicables.</p><p v-if="a.target.bodyArmor&&a.damageType!=='neuro'&&a.attackMode!=='foudre'">Armure corporelle de la forme : {{a.target.bodyArmor}} (meilleure protection corporelle retenue).</p><p v-if="a.target.reductions?.[a.damageType]">Réduction du profil : {{ a.target.reductions[a.damageType] }}</p><label v-for="p in a.target.protections" :key="p.id" class="check"><input v-model="drafts[a.id].protectionIds" type="checkbox" :value="p.id" /> {{ p.name }} — {{ p.text }}</label><div class="combat-fields"><label>Armure du profil<input v-model.number="drafts[a.id].armor" :disabled="a.damageType==='neuro'||a.attackMode==='foudre'" type="number" min="0" max="100" required /></label><label>Armure supplémentaire applicable<input v-model.number="drafts[a.id].extraArmor" :disabled="a.damageType==='neuro'||a.attackMode==='foudre'" type="number" min="0" max="100" required /></label><label>{{a.attackMode==='foudre'?'MJ · protection électrique arbitrée':'Réduction supplémentaire applicable'}}<input :disabled="a.attackMode==='foudre'&&!room.canManage" v-model.number="drafts[a.id].extraReduction" @input="drafts[a.id].electricProtectionConfirmed=false" type="number" min="0" max="100" required /></label></div><template v-if="a.attackMode==='foudre'"><p>Seules les réductions électriques des protections possédées sélectionnées et du profil sont automatiques. Armure corporelle, plaques et Kevlar : aucune réduction. Le MJ arbitre toute isolation/Faraday ou protection surnaturelle sans valeur électrique explicite.</p><template v-if="room.canManage&&drafts[a.id].extraReduction>0"><label>Source de la protection électrique<input v-model="drafts[a.id].electricProtectionNote" @input="drafts[a.id].electricProtectionConfirmed=false" aria-label="Source de la protection électrique" maxlength="200" required /></label><label class="check"><input v-model="drafts[a.id].electricProtectionConfirmed" type="checkbox" /> Le MJ confirme cette protection et sa valeur contre la Foudre.</label></template></template><small>Coche seulement les protections portées et applicables. Meilleure armure portée + meilleure armure corporelle ; pas de double cumul. Ajuste les effets conditionnels, pouvoirs, charges ablatives ou protections spéciales d’après leur texte. La protection matérielle est proposée pour les dégâts physiques ; confirme sa pertinence pour les effets particuliers.</small></fieldset>
 <div v-if="a.target.damagePowers?.length" class="damage-power"><label>Capacité de réduction<select v-model="drafts[a.id].damagePowerId" @change="drafts[a.id].damageContextConfirmed=false" :aria-label="`Capacité de réduction de ${a.target.name}`"><option value="">Aucune capacité supplémentaire</option><option v-for="p in a.target.damagePowers" :key="p.id" :value="p.id" :disabled="p.used">{{p.name}} · {{(p.effects??[]).map(effectText).join(' · ')}}{{p.used?' · déjà utilisée':''}}</option></select></label><label v-if="damagePower(a)?.context" class="check"><input v-model="drafts[a.id].damageContextConfirmed" type="checkbox" /> Je confirme : {{damagePower(a).context}}</label></div>
 <label v-if="a.damageType==='occulte'&&a.target.aura?.aura>0">Égide d’Aura<select v-model.number="drafts[a.id].auraSpend" :aria-label="`Aura à investir pour ${a.target.name}`"><option :value="0">Ne pas investir d’Aura</option><option v-for="n in Math.min(3,a.target.aura.aura)" :key="n" :value="n">{{n}} Aura · réduction {{n*a.target.aura.egidePerAura}}</option></select></label>
 <fieldset v-if="a.damageType==='neuro'&&a.target.neuroSacrificePrograms?.length"><legend>Sacrifier un programme chargé</legend><p>Chaque copie sacrifiée retire 3 dégâts Neuro. Le programme cesse d’être chargé et ne peut plus être réutilisé dans cette scène.</p><label v-for="p in a.target.neuroSacrificePrograms" :key="p.id" class="check"><input v-model="drafts[a.id].sacrificePrograms" type="checkbox" :value="p.id" /> {{p.label}} · −3 dégâts Neuro</label></fieldset>
 <details v-if="a.target.guardItems?.token?.remaining>0||a.target.protections.some((p:any)=>p.ablation)||a.lightning?.ignoreMagicProtection||a.lightning?.erodesProtection"><summary>Protections à charge et effets particuliers</summary><label v-if="a.target.guardItems?.token?.remaining>0" class="check"><input v-model="drafts[a.id].guardToken" type="checkbox" /> Jeton de Garde · −2 dégâts surnaturels · 1 PA · détruit après usage ({{a.target.guardItems.token.remaining}} restant)</label><p v-for="p in a.target.protections.filter((p:any)=>p.ablation)" :key="p.id">{{p.name}} · {{p.ablativeRemaining}} / {{p.ablation}} impacts restants</p><template v-if="a.target.protections.some((p:any)=>p.itemId==='modules-d-armure-plaques-ablatives')"><label>Armure portant les plaques<select v-model="drafts[a.id].ablativeHostId"><option value="">Choisir…</option><option v-for="p in a.target.protections.filter((p:any)=>p.itemId!=='modules-d-armure-plaques-ablatives')" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label class="check"><input v-model="drafts[a.id].ablativeMountedConfirmed" type="checkbox" /> Les plaques sont réellement montées sur cette protection sélectionnée.</label></template><label v-if="a.lightning?.ignoreMagicProtection&&room.canManage">Part magique de la protection électrique<input v-model.number="drafts[a.id].magicalProtection" type="number" min="0" max="100" /></label><template v-if="a.lightning?.erodesProtection&&room.canManage"><label class="check"><input v-model="drafts[a.id].erodeProtection" type="checkbox" /> Sacrifier 2 dégâts avant réduction pour éroder une protection</label><template v-if="drafts[a.id].erodeProtection"><label>Couche directement touchée<select v-model="drafts[a.id].erosionLayerId"><option value="">Choisir…</option><option v-for="p in a.target.protections" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Valeur de cette couche<input v-model.number="drafts[a.id].erosionAmount" type="number" min="0" max="100" /></label><label class="check"><input v-model="drafts[a.id].erosionMaterial" type="checkbox" /> Protection matérielle</label><label class="check"><input v-model="drafts[a.id].erosionConfirmed" type="checkbox" /> La couche a réellement été touchée et peut être érodée.</label></template></template></details>
 <p v-if="a.electricDiversion?.success">La décharge est détournée : aucun impact ni consommation de Rune de Garde.</p><p class="damage-preview"><template v-if="['melee','foudre'].includes(preview(a).attackMode)">Marge {{ preview(a).margin }} + arme {{ a.damage }}</template><template v-else-if="preview(a).attackMode==='margin'">Marge {{ preview(a).margin }}</template><template v-else-if="preview(a).attackMode==='fixed'">Dégâts fixes {{a.damage}}</template><template v-else>{{preview(a).multiplier}} × arme {{a.damage}} (marge {{preview(a).margin}})</template> + bonus {{ a.bonusDamage }} − protection matérielle {{ preview(a).material }} − réduction {{ preview(a).reduction }} = <strong>{{ preview(a).damage }} dégâts</strong></p><p v-if="preview(a).alteration">Une Altération cohérente est à déterminer avec le MJ.</p><button :disabled="busy||!canResolve(a)">Appliquer {{ preview(a).damage }} dégâts aux PV</button></form>
 <button v-if="room.canManage" :disabled="busy" @click="send('cancel',{attackId:a.id})">Annuler cette attaque</button></article>
</section>
</template>
