.combat-resolution{padding:16px;margin:0 0 24px;background:#0d1b2b;border:1px solid #355267;border-radius:8px;min-width:0}.combat-fields{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.combat-fields label{flex:1;min-width:130px}.combat-resolution label{display:grid;gap:6px;margin:10px 0}.combat-resolution .check{display:flex;align-items:center}.combat-resolution input:not([type=checkbox]),.combat-resolution select{box-sizing:border-box;width:100%;min-width:0;padding:10px;background:#08131f;color:#e6eef8;border:1px solid #526c80;border-radius:5px;font:inherit}.combat-resolution button{padding:10px;min-height:44px;margin:5px;background:#143247;color:#d5f6ff;border:1px solid #52758b;border-radius:5px;cursor:pointer}.combat-resolution button:disabled{opacity:.5;cursor:default}.combat-resolution summary{padding:12px;cursor:pointer}.combat-resolution fieldset{min-width:0;border:1px solid #355267}.reaction-card{padding:12px;border:1px solid #87bfae;border-radius:6px;margin:12px 0}.pending-attack{padding:12px;border:1px solid #52758b;border-radius:6px;margin:12px 0}.combat-resolution small{display:block;color:#b7c9d6;line-height:1.5}.damage-preview{color:#b7efff}.power-rule,.attack-context,.damage-power,.weapon-ruling{padding:12px;border:1px solid #54798f;border-radius:5px;background:#132b3d}.weapon-ruling p,.power-rule p{margin:6px 0;line-height:1.5}@media(max-width:500px){.combat-resolution{padding:10px}.combat-fields{display:grid;grid-template-columns:minmax(0,1fr);align-items:start}.combat-fields label{min-width:0}.combat-resolution button{margin:5px 0}.pending-attack{padding:10px}}
